    [2933]={name="Seal of Wrynn",sourceType="quest_reward",instructions="Reward from the quest “An Audience with the King”. In Stormwind City.",zone="Stormwind City",questName="An Audience with the King",lore="I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind."},
