    [3273]={name="Rugged Mail Vest",sourceType="quest_reward",instructions="Reward from the quest “Night Web's Hollow” — pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Night Web's Hollow",lore="One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."},
