    [4854]={name="Demon Scarred Cloak",sourceType="world_drop",instructions="Drops from Ghost Howl (rare spawn) in Thunder Bluff.",zone="Thunder Bluff",npc="Ghost Howl"},
    [4910]={name="Painted Chain Gloves",sourceType="quest_reward",instructions="Reward from the quest “The Hunt Begins” — pick it over the other choices. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="The Hunt Begins",lore="You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff."},
    [4911]={name="Thick Bark Buckler",sourceType="quest_reward",instructions="Reward from the quest “Attack on Camp Narache”. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="Attack on Camp Narache",lore="After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache."},
    [4913]={name="Painted Chain Belt",sourceType="quest_reward",instructions="Reward from the quest “The Hunt Continues” — pick it over the other choices. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="The Hunt Continues",lore="A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival."},
    [4917]={name="Battleworn Chain Leggings",sourceType="quest_reward",instructions="Reward from the quest “Sarkoth” — pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Sarkoth",lore="Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."},
    [4935]={name="Wide Metal Girdle",sourceType="quest_reward",instructions="Reward from the quest “From The Wreckage....” — pick it over the other choices. In Durotar.",zone="Durotar",questName="From The Wreckage....",lore="One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."},
    [4939]={name="Steady Bastard Sword",sourceType="quest_reward",instructions="Reward from the quest “Skull Rock” — pick it over the other choices. In Durotar.",zone="Durotar",questName="Skull Rock",lore=". The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars."},
    [4946]={name="Lightweight Boots",sourceType="quest_reward",instructions="Reward from the quest “Zalazane” — pick it over the other choices. In Durotar.",zone="Durotar",questName="Zalazane",lore="The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway."},
    [4969]={name="Fortified Bindings",sourceType="quest_reward",instructions="Reward from the quest “Dwarven Digging” — pick it over the other choices. In Mulgore.",zone="Mulgore",questName="Dwarven Digging",lore="There are dwarves preparing a dig site to the northwest. They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings."},
    [4975]={name="Vigilant Buckler",sourceType="quest_reward",instructions="Reward from the quest “Malin's Request” — pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Malin's Request",lore="Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."},
    [4979]={name="Enchanted Stonecloth Bracers",sourceType="quest_reward",instructions="Reward from the quest “Stone Is Better than Cloth”. In Badlands.",zone="Badlands",questName="Stone Is Better than Cloth",lore="Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."},
    [4998]={name="Blood Ring",sourceType="world_drop",instructions="World drop — drops from 363 creature types around level 19-26. Also found on the auction house."},
    [5002]={name="Glowing Green Talisman",sourceType="world_drop",instructions="World drop — drops from 262 creature types around level 25-31. Also found on the auction house."},
    [5003]={name="Crystal Starfire Medallion",sourceType="world_drop",instructions="World drop — drops from 254 creature types around level 26-32. Also found on the auction house."},
    [5111]={name="Rathorian's Cape",sourceType="world_drop",instructions="Drops from Rathorian (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Rathorian"},
    [5187]={name="Rhahk'Zor's Hammer",sourceType="boss_drop",instructions="Drops from Rhahk'Zor in The Deadmines.",zone="The Deadmines",npc="Rhahk'Zor"},
    [5195]={name="Gold-flecked Gloves",sourceType="world_drop",instructions="Drops from Sneed (rare elite).",npc="Sneed"},
    [5196]={name="Smite's Reaver",sourceType="boss_drop",instructions="Drops from Mr. Smite in The Deadmines.",zone="The Deadmines",npc="Mr. Smite"},
    [5254]={name="Rugged Spaulders",sourceType="boss_drop",instructions="Drops from Rethilgore in Shadowfang Keep.",zone="Shadowfang Keep",npc="Rethilgore"},
    [5257]={name="Dark Hooded Cape",sourceType="world_drop",instructions="Drops from Nimar the Slayer (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Nimar the Slayer"},
    [5274]={name="Rose Mantle",sourceType="quest_reward",instructions="Reward from the quest “Morganth”. In Redridge Mountains.",zone="Redridge Mountains",questName="Morganth",lore="After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."},
    [5275]={name="Binding Girdle",sourceType="quest_reward",instructions="Reward from the quest “The Disruption Ends” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5310]={name="Sea Dog Britches",sourceType="quest_reward",instructions="Reward from the quest “The Guns of Northwatch” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Guns of Northwatch",lore="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."},
    [5311]={name="Buckled Boots",sourceType="quest_reward",instructions="Reward from the quest “Free From the Hold” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Free From the Hold",lore="Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."},
    [5312]={name="Riveted Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Free From the Hold” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Free From the Hold",lore="Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."},
    [5319]={name="Bashing Pauldrons",sourceType="world_drop",instructions="Drops from Haren Swifthoof (rare elite) in The Loch.",zone="The Loch",npc="Haren Swifthoof"},
    [5320]={name="Padded Lamellar Boots",sourceType="quest_reward",instructions="Reward from the quest “Stolen Booty” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Stolen Booty",lore="While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."},
    [5321]={name="Elegant Shortsword",sourceType="quest_reward",instructions="Reward from the quest “Serena Bloodfeather” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Serena Bloodfeather",lore="You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."},
    [5324]={name="Engineer's Hammer",sourceType="quest_reward",instructions="Reward from the quest “Samophlange” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5325]={name="Welding Shield",sourceType="quest_reward",instructions="Reward from the quest “Samophlange” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5328]={name="Cinched Belt",sourceType="quest_reward",instructions="Reward from the quest “The Disruption Ends” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5345]={name="Stonewood Hammer",sourceType="quest_reward",instructions="Reward from the quest “Centaur Bracers” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Centaur Bracers",lore="The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."},
    [5351]={name="Bounty Hunter's Ring",sourceType="quest_reward",instructions="Reward from the quest “Hezrul Bloodmark”. In The Barrens.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5395]={name="Woodland Shield",sourceType="quest_reward",instructions="Reward from the quest “Webwood Egg” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [5399]={name="Tracking Boots",sourceType="quest_reward",instructions="Reward from the quest “The Woodland Protector” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [5404]={name="Serpent's Shoulders",sourceType="boss_drop",instructions="Drops from Lady Anacondra in Wailing Caverns.",zone="Wailing Caverns",npc="Lady Anacondra"},
    [5423]={name="Boahn's Fang",sourceType="world_drop",instructions="Drops from Boahn (rare spawn) in Wailing Caverns.",zone="Wailing Caverns",npc="Boahn"},
    [5425]={name="Runescale Girdle",sourceType="world_drop",instructions="Drops from Trigore the Lasher (rare spawn) in Wailing Caverns.",zone="Wailing Caverns",npc="Trigore the Lasher"},
    [5443]={name="Gold-plated Buckler",sourceType="boss_drop",instructions="Drops from Miner Johnson in The Deadmines.",zone="The Deadmines",npc="Miner Johnson"},
    [5444]={name="Miner's Cape",sourceType="boss_drop",instructions="Drops from Miner Johnson in The Deadmines.",zone="The Deadmines",npc="Miner Johnson"},
    [5542]={name="Pearl-clasped Cloak",sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5589]={name="Moss-covered Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Oakenscowl” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Oakenscowl",lore="In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."},
    [5591]={name="Rain-spotted Cape",sourceType="quest_reward",instructions="Reward from the quest “The Enchanted Glade” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5592]={name="Shackled Girdle",sourceType="quest_reward",instructions="Reward from the quest “The Enchanted Glade” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5595]={name="Thicket Hammer",sourceType="quest_reward",instructions="Reward from the quest “Crown of the Earth” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Crown of the Earth",lore="Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."},
    [5611]={name="Tear of Grief",sourceType="quest_reward",instructions="Reward from the quest “For Love Eternal”. In Darkshore.",zone="Darkshore",questName="For Love Eternal",lore="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."},
    [5750]={name="Warchief's Girdle",sourceType="world_drop",instructions="Drops from Ma'ruk Wyrmscale (rare spawn) in Dun Algaz.",zone="Dun Algaz",npc="Ma'ruk Wyrmscale"},
    [5753]={name="Ruffled Chaplet",sourceType="world_drop",instructions="Drops from Terrowulf Packlord (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Terrowulf Packlord"},
    [5754]={name="Wolfpack Medallion",sourceType="world_drop",instructions="Drops from Terrowulf Packlord (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Terrowulf Packlord"},
    [5757]={name="Hardwood Cudgel",sourceType="quest_reward",instructions="Reward from the quest “Mathystra Relics” — pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Mathystra Relics",lore="The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!"},
    [5761]={name="Anvilmar Sledge",sourceType="quest_reward",instructions="Reward from the quest “The Troll Cave” — pick it over the other choices. In Coldridge Valley.",zone="Coldridge Valley",questName="The Troll Cave",lore="My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."},
    [5777]={name="Brave's Axe",sourceType="quest_reward",instructions="Reward from the quest “Rite of Strength” — pick it over the other choices. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="Rite of Strength",lore="The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."},
    [5781]={name="Murloc Scale Breastplate",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5819]={name="Sunblaze Coif",sourceType="world_drop",instructions="World drop — drops from 38 creature types around level 29-40. Also found on the auction house."},
    [5941]={name="Brass Scale Pants",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Maggot Eye” — pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="Wanted: Maggot Eye",lore="Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken. This despicable villain has been stealing corpses for use by the Lich King's army."},
    [5943]={name="Rift Bracers",sourceType="world_drop",instructions="Drops from Arugal's Voidwalker.",npc="Arugal's Voidwalker"},
    [5944]={name="Greaves of the People's Militia",sourceType="quest_reward",instructions="Reward from the quest “Red Leather Bandanas” — pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [5962]={name="Guardian Pants",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5967]={name="Girdle of Nobility",sourceType="world_drop",instructions="Drops from Brainwashed Noble (rare spawn) in The Deadmines.",zone="The Deadmines",npc="Brainwashed Noble"},
    [5970]={name="Serpent Gloves",sourceType="boss_drop",instructions="Drops from Lord Serpentis in Wailing Caverns.",zone="Wailing Caverns",npc="Lord Serpentis"},
    [6061]={name="Graystone Bracers",sourceType="quest_reward",instructions="Reward from the quest “Timberling Sprouts” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Timberling Sprouts",lore="Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."},
    [6063]={name="Cold Steel Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Graverobbers” — pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="Graverobbers",lore="The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."},
    [6084]={name="Stormwind Guard Leggings",sourceType="quest_reward",instructions="Reward from the quest “Wanted:  \"Hogger\"” — pick it over the other choices. In Elwynn Forest.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6087]={name="Chausses of Westfall",sourceType="quest_reward",instructions="Reward from the quest “The Defias Brotherhood” — pick it over the other choices. In The Deadmines.",zone="The Deadmines",questName="The Defias Brotherhood",lore="Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."},
    [6177]={name="Ironwrought Bracers",sourceType="quest_reward",instructions="Reward from the quest “Tundra MacGrann's Stolen Stash” — pick it over the other choices. In Dun Morogh.",zone="Dun Morogh",questName="Tundra MacGrann's Stolen Stash",lore="I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."},
    [6180]={name="Slarkskin",sourceType="world_drop",instructions="Drops from Slark (rare spawn) in Westfall.",zone="Westfall",npc="Slark"},
    [6187]={name="Dwarven Defender",sourceType="quest_reward",instructions="Reward from the quest “In Defense of the King's Lands” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="In Defense of the King's Lands",lore="our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."},
    [6188]={name="Mud Stompers",sourceType="quest_reward",instructions="Reward from the quest “Protecting the Shipment” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="Protecting the Shipment",lore="Ready to go? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me."},
    [6189]={name="Durable Chain Shoulders",sourceType="quest_reward",instructions="Reward from the quest “WANTED: Chok'sul” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
    [6191]={name="Kimbra Boots",sourceType="quest_reward",instructions="Reward from the quest “WANTED: Chok'sul” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
    [6195]={name="Wax-polished Armor",sourceType="world_drop",instructions="Drops from Grizlak (rare spawn).",npc="Grizlak"},
    [6199]={name="Black Widow Band",sourceType="world_drop",instructions="Drops from Leech Widow (rare spawn) in Dun Algaz.",zone="Dun Algaz",npc="Leech Widow"},
    [6203]={name="Thuggish Shield",sourceType="world_drop",instructions="Drops from Thuros Lightfingers (rare spawn) in Elwynn Forest.",zone="Elwynn Forest",npc="Thuros Lightfingers"},
    [6205]={name="Burrowing Shovel",sourceType="world_drop",instructions="Drops from Master Digger (rare spawn) in Westfall.",zone="Westfall",npc="Master Digger"},
    [6223]={name="Crest of Darkshire",sourceType="quest_reward",instructions="Reward from the quest “Bride of the Embalmer”. In Duskwood.",zone="Duskwood",questName="Bride of the Embalmer",lore="The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."},
    [6243]={name="Green Woolen Robe",sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [6263]={name="Blue Overalls",sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [6282]={name="Sacred Burial Trousers",sourceType="quest_reward",instructions="Reward from the quest “Battle of Hillsbrad” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Battle of Hillsbrad",lore="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."},
    [6319]={name="Girdle of the Blindwatcher",sourceType="boss_drop",instructions="Drops from Odo the Blindwatcher in Shadowfang Keep.",zone="Shadowfang Keep",npc="Odo the Blindwatcher"},
    [6320]={name="Commander's Crest",sourceType="boss_drop",instructions="Drops from Commander Springvale in Shadowfang Keep.",zone="Shadowfang Keep",npc="Commander Springvale"},
    [6321]={name="Silverlaine's Family Seal",sourceType="boss_drop",instructions="Drops from Baron Silverlaine in Shadowfang Keep.",zone="Shadowfang Keep",npc="Baron Silverlaine"},
    [6324]={name="Robes of Arugal",sourceType="boss_drop",instructions="Drops from Archmage Arugal in Shadowfang Keep.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."},
    [6332]={name="Black Pearl Ring",sourceType="world_drop",instructions="Drops from Lady Vespira (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Lady Vespira"},
    [6336]={name="Infantry Tunic",sourceType="world_drop",instructions="World drop — drops from 380 creature types around level 8-14. Also found on the auction house."},
    [6337]={name="Infantry Leggings",sourceType="world_drop",instructions="World drop — drops from 466 creature types around level 6-14. Also found on the auction house."},
