    [6413]={name="Chief Brigadier Bracers",sourceType="world_drop",instructions="World drop — drops from 385 creature types around level 32-39. Also found on the auction house."},
    [6414]={name="Seal of Sylvanas",sourceType="quest_reward",instructions="Reward from the quest “Arugal Must Die”. In Shadowfang Keep.",zone="Shadowfang Keep",questName="Arugal Must Die",lore="Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."},
    [6425]={name="Blackforge Girdle",sourceType="world_drop",instructions="World drop — drops from 315 creature types around level 38-45. Also found on the auction house."},
