    [6463]={name="Deep Fathom Ring",sourceType="world_drop",instructions="Drops from Mutanus the Devourer (rare elite).",npc="Mutanus the Devourer"},
    [6465]={name="Robe of the Moccasin",sourceType="boss_drop",instructions="Drops from Lord Cobrahn in Wailing Caverns.",zone="Wailing Caverns",npc="Lord Cobrahn"},
    [6473]={name="Armor of the Fang",sourceType="boss_drop",instructions="Drops from Lord Pythas in Wailing Caverns.",zone="Wailing Caverns",npc="Lord Pythas"},
    [6477]={name="Grassland Sash",sourceType="quest_reward",instructions="Reward from the quest “Consumed by Hatred” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Consumed by Hatred",lore="Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."},
    [6481]={name="Dagmire Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Deviate Eradication” — pick it over the other choices. In Wailing Caverns.",zone="Wailing Caverns",questName="Deviate Eradication",lore="Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was."},
    [6482]={name="Firewalker Boots",sourceType="quest_reward",instructions="Reward from the quest “Elixir of Pain” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Elixir of Pain",lore="Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."},
    [6502]={name="Violet Scale Armor",sourceType="quest_reward",instructions="Reward from the quest “Egg Hunt” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Egg Hunt",lore="Hey. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants."},
    [6504]={name="Wingblade",sourceType="quest_reward",instructions="Reward from the quest “Leaders of the Fang” — pick it over the other choices. In Wailing Caverns.",zone="Wailing Caverns",questName="Leaders of the Fang",lore="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."},
