    [11229]={name="Brightscale Girdle",sourceType="quest_reward",instructions="Reward from the quest “The Branch of Cenarius” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="The Branch of Cenarius",lore="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."},
