    [11815]={name="Hand of Justice",sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Prints five Strength and eight Stamina and is worth vastly more than that: the extra attack it grants is the reason a Blackrock Depths trinket stayed in raid sets for years.",proc="Equip: Chance on melee hit to gain 1 extra attack. (2s cooldown)"},
    [11819]={name="Second Wind",sourceType="boss_drop",instructions="Drops from Golem Lord Argelmach in Blackrock Depths.",zone="Blackrock Depths",npc="Golem Lord Argelmach",proc="Use: Restores 30 mana every 1 sec for 10 sec. (15 Min Cooldown)"},
