    [16891]={name="Claystone Shortsword",sourceType="quest_reward",instructions="Reward from the quest “Arachnophobia” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Arachnophobia",lore="Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."},
