    [16986]={name="Sandspire Gloves",sourceType="quest_reward",instructions="Reward from the quest “New Life” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="New Life",lore="As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."},
    [17006]={name="Cobalt Legguards",sourceType="quest_reward",instructions="Reward from the quest “King of the Foulweald” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="King of the Foulweald",lore="another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."},
