    [20505]={name="Chivalrous Signet",sourceType="quest_reward",instructions="Reward from the quest “Forging the Mightstone” — pick it over the other choices.",questName="Forging the Mightstone",lore="Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead. This is no trivial task. Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself."},
