    [20640]={name="Southsea Head Bucket",sourceType="quest_reward",instructions="Reward from the quest “Southsea Shakedown” — pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Southsea Shakedown",lore="They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."},
