    [22087]={name="Soulforge Boots",sourceType="quest_reward",instructions="Reward from the quest “Anthion's Parting Words”. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [22090]={name="Soulforge Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Just Compensation”. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."},
    [22149]={name="Beads of Ogre Mojo",sourceType="quest_reward",instructions="Reward from the quest “Falrin's Vendetta” — pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
