    [22667]={name="Bracers of Hope",sourceType="quest_reward",instructions="Reward from the quest “Epic Armaments of Battle - Friend of the Dawn” — pick it over the other choices. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."},
    [22671]={name="Icebane Bracers",sourceType="quest_reward",instructions="Reward from the quest “Icebane Bracers”. In Naxxramas.",zone="Naxxramas",questName="Icebane Bracers",lore="Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers."},
    [22699]={name="Icebane Leggings",sourceType="quest_reward",instructions="Reward from the quest “The Only Song I Know...” — pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Only Song I Know...",lore="You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"},
    [22732]={name="Mark of C'Thun",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22798]={name="Might of Menethil",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Menethil was the royal line of Lordaeron -- King Terenas, and his son Arthas, who became the Lich King. A warhammer carrying that name, guarded by the lich who served Arthas, is not an accident."},
    [22819]={name="Shield of Condemnation",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22936]={name="Wristguards of Vengeance",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22938]={name="Cryptfiend Silk Cloak",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22939]={name="Band of Unanswered Prayers",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22940]={name="Icebane Pauldrons",sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina in Naxxramas.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22942]={name="The Widow's Embrace",sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina in Naxxramas.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22960]={name="Cloak of Suturing",sourceType="boss_drop",instructions="Drops from Patchwerk in Naxxramas.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
    [22981]={name="Gluth's Missing Collar",sourceType="boss_drop",instructions="Drops from Gluth in Naxxramas.",zone="Naxxramas",npc="Gluth",lore="A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."},
    [22988]={name="The End of Dreams",sourceType="boss_drop",instructions="Drops from Grobbulus in Naxxramas.",zone="Naxxramas",npc="Grobbulus",lore="A walking vat. The Scourge used him to field-test new strains of the plague on whatever wandered into Naxxramas."},
    [23006]={name="Libram of Light",sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer in Naxxramas.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [23019]={name="Icebane Helmet",sourceType="boss_drop",instructions="Drops from Heigan the Unclean in Naxxramas.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23036]={name="Necklace of Necropsy",sourceType="boss_drop",instructions="Drops from Heigan the Unclean in Naxxramas.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23038]={name="Band of Unnatural Forces",sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23043]={name="The Face of Death",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23045]={name="Shroud of Dominion",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23047]={name="Eye of the Dead",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases healing done by the next 5 spells by up to 450 and damage done by up to 150 for 30 sec. (750ms cooldown) (2 Min Cooldown)"},
